export const CHARTS: Record<string, string> = {"CommonGround_GilensPage_v1.html": "<!DOCTYPE html>\n<html lang=\"en\" data-theme=\"light\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Whose preferences actually become policy?</title>\n<style>\n  :root{\n    --bg:#fcfcfb; --panel:#ffffff; --ink:#26251f; --ink2:#575349; --muted:#8a8578;\n    --line:#e7e3d8; --grid:#efece3;\n    --people:#5E86A0; --elite:#B98A1F;\n    --shadow:0 1px 2px rgba(40,38,30,.06),0 4px 18px rgba(40,38,30,.06);\n  }\n  html[data-theme=\"dark\"]{\n    --bg:#1a1a19; --panel:#232320; --ink:#eceae2; --ink2:#c3bfb2; --muted:#928d7f;\n    --line:#38372f; --grid:#2c2b25;\n    --people:#7CA3BD; --elite:#E0C766;\n    --shadow:0 1px 2px rgba(0,0,0,.3),0 4px 20px rgba(0,0,0,.28);\n  }\n  *{box-sizing:border-box}\n  body{margin:0;background:var(--bg);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;line-height:1.5;-webkit-font-smoothing:antialiased}\n  .wrap{max-width:900px;margin:0 auto;padding:34px 24px 70px}\n  h1{font-family:Georgia,serif;font-size:26px;margin:0 0 5px;letter-spacing:-.01em}\n  .kicker{text-transform:uppercase;letter-spacing:.09em;font-size:11px;font-weight:700;color:var(--muted);margin:0 0 4px}\n  .sub{color:var(--ink2);font-size:15px;margin:0;max-width:760px}\n  .src{color:var(--muted);font-size:12px;margin-top:6px}\n  .topbar{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap}\n  .toggle{font-size:12.5px;border:1px solid var(--line);background:var(--panel);color:var(--ink2);border-radius:20px;padding:6px 13px;cursor:pointer}\n  .tiles{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:22px 0 6px}\n  @media(max-width:620px){.tiles{grid-template-columns:1fr}}\n  .tile{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:15px 16px;box-shadow:var(--shadow)}\n  .tile.people{border-left:4px solid var(--people)}\n  .tile.elite{border-left:4px solid var(--elite)}\n  .tile .lab{font-size:12px;color:var(--muted);font-weight:700;text-transform:uppercase;letter-spacing:.04em}\n  .tile .big{font-size:27px;font-weight:800;margin:6px 0 3px;font-variant-numeric:tabular-nums}\n  .tile.people .big{color:var(--people)} .tile.elite .big{color:var(--elite)}\n  .tile .vs{font-size:12.5px;color:var(--ink2);line-height:1.45}\n  .panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:18px 20px 16px;box-shadow:var(--shadow);margin-top:12px}\n  .panel h2{font-size:15px;margin:0 0 3px;font-family:Georgia,serif}\n  .panel .psub{font-size:12.5px;color:var(--muted);margin:0 0 16px}\n  .row{display:grid;grid-template-columns:200px 1fr;gap:14px;align-items:center;margin:13px 0}\n  @media(max-width:620px){.row{grid-template-columns:1fr}}\n  .rlab{font-size:13.5px;color:var(--ink2);font-weight:600}\n  .rlab b{color:var(--ink)}\n  .track{position:relative;background:var(--grid);border-radius:8px;height:38px;overflow:hidden}\n  .fill{height:100%;border-radius:8px;display:flex;align-items:center;justify-content:flex-end;padding-right:11px;color:#fff;font-weight:800;font-size:14px;min-width:40px}\n  .fill.people{background:var(--people)} .fill.elite{background:var(--elite)}\n  .axnote{font-size:11.5px;color:var(--muted);margin-top:6px}\n  .callout{background:var(--panel);border:1px solid var(--line);border-left:4px solid var(--elite);border-radius:10px;padding:14px 16px;margin-top:14px;box-shadow:var(--shadow);font-size:13.5px;color:var(--ink2);line-height:1.55}\n  .callout b{color:var(--ink)}\n  .read{font-size:14.5px;color:var(--ink2);margin-top:16px;line-height:1.6;border-left:3px solid var(--people);padding-left:16px}\n  .read b{color:var(--ink)}\n  .dual{background:var(--panel);border:1px solid var(--line);border-left:4px solid var(--elite);border-radius:10px;padding:11px 14px;margin-top:14px;font-size:13px;color:var(--ink2);line-height:1.5;box-shadow:var(--shadow)}\n  .dual b{color:var(--ink)}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <div class=\"topbar\">\n    <div>\n      <p class=\"kicker\">Common Ground · the problem under Government Performance &amp; Money in Politics</p>\n      <h1>Whose preferences actually become policy?</h1>\n      <p class=\"sub\">Researchers tested <b>1,779 federal policy decisions</b> (1981–2002) against what different groups wanted. Once you account for what economic elites and organized interest groups want, the average citizen's own preferences make <b>almost no independent difference</b> to what becomes law.</p>\n      <p class=\"src\">Source: Gilens &amp; Page, \"Testing Theories of American Politics,\" 2014 (1,779 policy outcomes, 1981–2002). Figures are the study's Figure 1 predicted probabilities.</p>\n    </div>\n    <button class=\"toggle\" id=\"themeBtn\">◐ Dark</button>\n  </div>\n\n  <div class=\"dual\"><b>One finding, two planks.</b> You'll see this same chart under both <b>Government Performance</b> (is government serving the people?) and <b>Money in Politics</b>. They share this diagnosis — and Money in Politics is the plank whose policies go after the specific cause it points to: <b>the outsized pull of money on what becomes law.</b></div>\n\n  <div class=\"tiles\">\n    <div class=\"tile people\">\n      <div class=\"lab\">If average citizens want it</div>\n      <div class=\"big\">no real change</div>\n      <div class=\"vs\">Whether few or many ordinary Americans favor a policy, its odds of passing stay about <b>30%</b>.</div>\n    </div>\n    <div class=\"tile elite\">\n      <div class=\"lab\">If economic elites want it</div>\n      <div class=\"big\">18% → 45%</div>\n      <div class=\"vs\">As elite support climbs from low to high, a policy's odds of passing <b>more than double</b>.</div>\n    </div>\n  </div>\n\n  <div class=\"panel\">\n    <h2>How much each group's support actually moves the odds</h2>\n    <p class=\"psub\">Change in a policy's chance of becoming law as a group goes from opposed to strongly in favor</p>\n    <div class=\"row\">\n      <div class=\"rlab\"><b>Average citizens</b></div>\n      <div class=\"track\"><div class=\"fill people\" style=\"width:3%\"></div></div>\n    </div>\n    <div class=\"row\">\n      <div class=\"rlab\"><b>Economic elites &amp;<br>organized interests</b></div>\n      <div class=\"track\"><div class=\"fill elite\" style=\"width:96%\">+27 points</div></div>\n    </div>\n    <p class=\"axnote\">The public's preference, on its own, barely moves the outcome; elite and organized-interest support moves it a lot.</p>\n  </div>\n\n  <div class=\"callout\">\n    Across all 1,779 decisions, the average citizen's <b>independent</b> influence on what became law was <b>statistically indistinguishable from zero</b> — while economic elites and organized interest groups consistently moved outcomes. That's not \"the public always loses\": when ordinary people happen to want what elites want, it often passes. It's that <b>when they diverge, the public's preference alone barely counts.</b>\n  </div>\n\n  <p class=\"read\"><b>Reading it.</b> On paper the system runs on votes; in practice, issue after issue, it's organized money and influence that move the result. That single finding sits under two questions at once — whether government serves ordinary people, and whether votes or dollars decide policy. On this evidence, it's dollars.</p>\n</div>\n\n<script>\ndocument.getElementById('themeBtn').onclick=function(){\n  const h=document.documentElement,dark=h.getAttribute('data-theme')==='dark';\n  h.setAttribute('data-theme',dark?'light':'dark');this.textContent=dark?'◐ Dark':'◑ Light';};\n</script>\n</body>\n</html>\n", "CommonGround_Healthcare_ValueGap_v1.html": "<!DOCTYPE html>\n<html lang=\"en\" data-theme=\"light\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>The Health Value Gap — what America pays vs. what we get</title>\n<style>\n  :root{\n    --bg:#fcfcfb; --panel:#ffffff; --ink:#26251f; --ink2:#575349; --muted:#8a8578;\n    --line:#e7e3d8; --grid:#efece3;\n    --peer:#8A8578; --us:#C0483F; --avg:#C6972F;\n    --shadow:0 1px 2px rgba(40,38,30,.06),0 4px 18px rgba(40,38,30,.06);\n  }\n  html[data-theme=\"dark\"]{\n    --bg:#1a1a19; --panel:#232320; --ink:#eceae2; --ink2:#c3bfb2; --muted:#928d7f;\n    --line:#38372f; --grid:#2c2b25;\n    --peer:#9AA096; --us:#E07A72; --avg:#E0C766;\n    --shadow:0 1px 2px rgba(0,0,0,.3),0 4px 20px rgba(0,0,0,.28);\n  }\n  *{box-sizing:border-box}\n  body{margin:0;background:var(--bg);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;line-height:1.5;-webkit-font-smoothing:antialiased}\n  .wrap{max-width:960px;margin:0 auto;padding:34px 24px 70px}\n  h1{font-family:Georgia,serif;font-size:27px;margin:0 0 5px;letter-spacing:-.01em}\n  .kicker{text-transform:uppercase;letter-spacing:.09em;font-size:11px;font-weight:700;color:var(--muted);margin:0 0 4px}\n  .sub{color:var(--ink2);font-size:15.5px;margin:0;max-width:760px}\n  .src{color:var(--muted);font-size:12px;margin-top:6px}\n  .topbar{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap}\n  .toggle{font-size:12.5px;border:1px solid var(--line);background:var(--panel);color:var(--ink2);border-radius:20px;padding:6px 13px;cursor:pointer}\n  .tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:22px 0 10px}\n  .tile{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:15px 16px;box-shadow:var(--shadow)}\n  .tile .lab{font-size:12px;color:var(--muted);font-weight:600;text-transform:uppercase;letter-spacing:.04em}\n  .tile .big{font-size:26px;font-weight:800;margin:6px 0 2px;font-variant-numeric:tabular-nums}\n  .tile .big .us{color:var(--us)}\n  .tile .vs{font-size:13px;color:var(--ink2)}\n  .tile .vs b{color:var(--ink)}\n  .tile .delta{font-size:12.5px;font-weight:700;margin-top:5px}\n  .tile .delta.bad{color:var(--us)}\n  .panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:18px 20px 14px;box-shadow:var(--shadow);margin-top:12px}\n  .legend{display:flex;gap:18px;flex-wrap:wrap;font-size:13px;color:var(--ink2);margin-bottom:6px}\n  .legend span{display:inline-flex;align-items:center;gap:7px}\n  .dot{width:12px;height:12px;border-radius:50%;display:inline-block}\n  svg{display:block;width:100%;height:auto;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif}\n  .tip{position:fixed;pointer-events:none;opacity:0;transition:opacity .1s;background:#26251f;color:#fff;font-size:12.5px;padding:7px 10px;border-radius:7px;box-shadow:0 4px 16px rgba(0,0,0,.3);z-index:50}\n  .note{font-size:12.5px;color:var(--muted);margin-top:10px;line-height:1.5}\n  .read{font-size:14.5px;color:var(--ink2);margin-top:18px;line-height:1.6;border-left:3px solid var(--us);padding-left:16px}\n  .read b{color:var(--ink)}\n  a{color:var(--peer)}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <div class=\"topbar\">\n    <div>\n      <p class=\"kicker\">Common Ground · Healthcare plank · the diagnostic</p>\n      <h1>The Value Gap: what America pays vs. what we get</h1>\n      <p class=\"sub\">Every comparable wealthy country spends far less on health care than the United States — and every one of them lives longer. That gap — paying more and getting less — is the heart of the problem.</p>\n      <p class=\"src\">Sources: Peterson-KFF Health System Tracker (U.S. and comparable-country average, 2024). Per-country points: OECD Health Statistics, ~2023 (approximate).</p>\n    </div>\n    <button class=\"toggle\" id=\"themeBtn\">◐ Dark</button>\n  </div>\n\n  <div class=\"tiles\">\n    <div class=\"tile\">\n      <div class=\"lab\">Spending per person</div>\n      <div class=\"big\"><span class=\"us\">$14,775</span></div>\n      <div class=\"vs\">vs <b>$7,860</b> comparable-country avg</div>\n      <div class=\"delta bad\">▲ 88% more</div>\n    </div>\n    <div class=\"tile\">\n      <div class=\"lab\">Life expectancy</div>\n      <div class=\"big\"><span class=\"us\">79.0</span> yrs</div>\n      <div class=\"vs\">vs <b>82.7</b> comparable-country avg</div>\n      <div class=\"delta bad\">▼ 3.7 years less</div>\n    </div>\n    <div class=\"tile\">\n      <div class=\"lab\">Share of the economy</div>\n      <div class=\"big\"><span class=\"us\">17.2%</span></div>\n      <div class=\"vs\">of GDP vs <b>11.2%</b> avg</div>\n      <div class=\"delta bad\">▲ 6 points of GDP</div>\n    </div>\n  </div>\n\n  <div class=\"panel\">\n    <div class=\"legend\">\n      <span><i class=\"dot\" style=\"background:var(--us)\"></i>United States</span>\n      <span><i class=\"dot\" style=\"background:var(--peer)\"></i>Comparable countries</span>\n      <span><i class=\"dot\" style=\"background:var(--avg);border-radius:2px\"></i>Comparable-country average</span>\n    </div>\n    <svg id=\"scatter\" viewBox=\"0 0 900 520\" role=\"img\" aria-label=\"Scatterplot of health spending per capita versus life expectancy\"></svg>\n    <p class=\"note\">Peer countries slope upward — more spending buys more life. The United States sits far to the right and near the bottom, breaking the pattern: the most money, the shortest lives among peers.</p>\n  </div>\n\n  <p class=\"read\"><b>Reading it.</b> If health spending simply bought longevity, the U.S. — spending nearly double the peer average — would be at the top. Instead it is last among these nations in life expectancy. The gap between what Americans pay and what they get back is the heart of it: <b>value</b>, not just cost. Every policy here is a way to close that gap.</p>\n</div>\n<div class=\"tip\" id=\"tip\"></div>\n\n<script>\nconst SVGNS='http://www.w3.org/2000/svg';\nconst el=(t,a)=>{const n=document.createElementNS(SVGNS,t);for(const k in a)n.setAttribute(k,a[k]);return n;};\nconst cssv=v=>getComputedStyle(document.body).getPropertyValue(v).trim();\nconst tip=document.getElementById('tip');\nfunction showTip(h,e){tip.innerHTML=h;tip.style.opacity=1;mv(e);}\nfunction mv(e){let x=e.clientX+12,y=e.clientY+12;if(x+180>innerWidth)x=e.clientX-180;tip.style.left=x+'px';tip.style.top=y+'px';}\nfunction hide(){tip.style.opacity=0;}\naddEventListener('mousemove',e=>{if(tip.style.opacity==1)mv(e);});\n\nconst data=[\n {c:'United States',x:14775,y:79.0,us:true},\n {c:'Switzerland',x:9800,y:84.0},\n {c:'Germany',x:8900,y:81.4},\n {c:'Austria',x:8200,y:81.8},\n {c:'Netherlands',x:7900,y:82.3},\n {c:'Sweden',x:7100,y:83.4},\n {c:'France',x:6900,y:82.8},\n {c:'Belgium',x:6900,y:82.3},\n {c:'Canada',x:6700,y:82.6},\n {c:'Australia',x:6600,y:83.6},\n {c:'United Kingdom',x:6300,y:81.3},\n {c:'Japan',x:5400,y:84.5},\n];\nconst avg={c:'Comparable-country average',x:7860,y:82.7};\n\nfunction draw(){\n  const W=900,H=520,m={t:20,r:24,b:56,l:56};\n  const svg=document.getElementById('scatter');svg.innerHTML='';\n  const iw=W-m.l-m.r, ih=H-m.t-m.b;\n  const xmin=4000,xmax=16000,ymin=76,ymax=86;\n  const X=v=>m.l+(v-xmin)/(xmax-xmin)*iw;\n  const Y=v=>m.t+ih-(v-ymin)/(ymax-ymin)*ih;\n  const grid=cssv('--grid'),muted=cssv('--muted'),line=cssv('--line');\n  const peer=cssv('--peer'),us=cssv('--us'),avgc=cssv('--avg'),ink2=cssv('--ink2');\n  // gridlines + axes\n  for(let gx=4000;gx<=16000;gx+=2000){\n    svg.appendChild(el('line',{x1:X(gx),x2:X(gx),y1:m.t,y2:m.t+ih,stroke:grid,'stroke-width':1}));\n    const t=el('text',{x:X(gx),y:m.t+ih+20,'text-anchor':'middle',fill:muted,'font-size':11});\n    t.textContent='$'+(gx/1000)+'k';svg.appendChild(t);\n  }\n  for(let gy=76;gy<=86;gy+=2){\n    svg.appendChild(el('line',{x1:m.l,x2:m.l+iw,y1:Y(gy),y2:Y(gy),stroke:grid,'stroke-width':1}));\n    const t=el('text',{x:m.l-9,y:Y(gy)+4,'text-anchor':'end',fill:muted,'font-size':11});t.textContent=gy;svg.appendChild(t);\n  }\n  // axis titles\n  const xt=el('text',{x:m.l+iw/2,y:H-8,'text-anchor':'middle',fill:ink2,'font-size':12.5,'font-weight':700});\n  xt.textContent='Health spending per person (US$, 2024)';svg.appendChild(xt);\n  const yt=el('text',{x:16,y:m.t+ih/2,'text-anchor':'middle',fill:ink2,'font-size':12.5,'font-weight':700,transform:`rotate(-90 16 ${m.t+ih/2})`});\n  yt.textContent='Life expectancy at birth (years)';svg.appendChild(yt);\n\n  // average crosshair (reference)\n  svg.appendChild(el('line',{x1:X(avg.x),x2:X(avg.x),y1:m.t,y2:m.t+ih,stroke:avgc,'stroke-width':1.5,'stroke-dasharray':'4,4','opacity':.6}));\n  svg.appendChild(el('line',{x1:m.l,x2:m.l+iw,y1:Y(avg.y),y2:Y(avg.y),stroke:avgc,'stroke-width':1.5,'stroke-dasharray':'4,4','opacity':.6}));\n\n  // peer points\n  data.filter(d=>!d.us).forEach(d=>{\n    const c=el('circle',{cx:X(d.x),cy:Y(d.y),r:6.5,fill:peer,'fill-opacity':.9,stroke:cssv('--panel'),'stroke-width':1.5});\n    c.addEventListener('mousemove',e=>showTip(`<b>${d.c}</b><br>$${d.x.toLocaleString()} · ${d.y} yrs`,e));\n    c.addEventListener('mouseleave',hide);svg.appendChild(c);\n    const t=el('text',{x:X(d.x),y:Y(d.y)-10,'text-anchor':'middle',fill:muted,'font-size':10});t.textContent=d.c;svg.appendChild(t);\n  });\n  // average marker\n  const am=el('rect',{x:X(avg.x)-6,y:Y(avg.y)-6,width:12,height:12,fill:avgc,stroke:cssv('--panel'),'stroke-width':1.5,transform:`rotate(45 ${X(avg.x)} ${Y(avg.y)})`});\n  am.addEventListener('mousemove',e=>showTip(`<b>Comparable-country average</b><br>$${avg.x.toLocaleString()} · ${avg.y} yrs`,e));\n  am.addEventListener('mouseleave',hide);svg.appendChild(am);\n\n  // US point (big, highlighted)\n  const u=data.find(d=>d.us);\n  svg.appendChild(el('circle',{cx:X(u.x),cy:Y(u.y),r:11,fill:us,stroke:cssv('--panel'),'stroke-width':2}));\n  const ut=el('text',{x:X(u.x),y:Y(u.y)+26,'text-anchor':'middle',fill:us,'font-size':13,'font-weight':800});\n  ut.textContent='United States';svg.appendChild(ut);\n  const ut2=el('text',{x:X(u.x),y:Y(u.y)+42,'text-anchor':'middle',fill:us,'font-size':11});\n  ut2.textContent='most spending, shortest lives';svg.appendChild(ut2);\n}\ndraw();\nlet rt;addEventListener('resize',()=>{clearTimeout(rt);rt=setTimeout(draw,150);});\ndocument.getElementById('themeBtn').onclick=function(){\n  const h=document.documentElement,dark=h.getAttribute('data-theme')==='dark';\n  h.setAttribute('data-theme',dark?'light':'dark');this.textContent=dark?'◐ Dark':'◑ Light';draw();};\n</script>\n</body>\n</html>\n", "CommonGround_Immigration_Backlog_v1.html": "<!DOCTYPE html>\n<html lang=\"en\" data-theme=\"light\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>The Immigration Backlog — a broken process</title>\n<style>\n  :root{\n    --bg:#fcfcfb; --panel:#ffffff; --ink:#26251f; --ink2:#575349; --muted:#8a8578;\n    --line:#e7e3d8; --grid:#efece3;\n    --bar:#C0483F; --bar2:#e0a59f; --accent:#5E86A0;\n    --shadow:0 1px 2px rgba(40,38,30,.06),0 4px 18px rgba(40,38,30,.06);\n  }\n  html[data-theme=\"dark\"]{\n    --bg:#1a1a19; --panel:#232320; --ink:#eceae2; --ink2:#c3bfb2; --muted:#928d7f;\n    --line:#38372f; --grid:#2c2b25;\n    --bar:#E07A72; --bar2:#7a4340; --accent:#7CA3BD;\n    --shadow:0 1px 2px rgba(0,0,0,.3),0 4px 20px rgba(0,0,0,.28);\n  }\n  *{box-sizing:border-box}\n  body{margin:0;background:var(--bg);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;line-height:1.5;-webkit-font-smoothing:antialiased}\n  .wrap{max-width:940px;margin:0 auto;padding:34px 24px 70px}\n  h1{font-family:Georgia,serif;font-size:27px;margin:0 0 5px;letter-spacing:-.01em}\n  .kicker{text-transform:uppercase;letter-spacing:.09em;font-size:11px;font-weight:700;color:var(--muted);margin:0 0 4px}\n  .sub{color:var(--ink2);font-size:15.5px;margin:0;max-width:770px}\n  .src{color:var(--muted);font-size:12px;margin-top:6px}\n  .topbar{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap}\n  .toggle{font-size:12.5px;border:1px solid var(--line);background:var(--panel);color:var(--ink2);border-radius:20px;padding:6px 13px;cursor:pointer}\n  .tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:22px 0 10px}\n  .tile{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:15px 16px;box-shadow:var(--shadow)}\n  .tile .lab{font-size:12px;color:var(--muted);font-weight:600;text-transform:uppercase;letter-spacing:.04em}\n  .tile .big{font-size:26px;font-weight:800;margin:6px 0 2px;font-variant-numeric:tabular-nums;color:var(--bar)}\n  .tile .vs{font-size:13px;color:var(--ink2)}\n  .panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:18px 20px 14px;box-shadow:var(--shadow);margin-top:12px}\n  svg{display:block;width:100%;height:auto;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif}\n  .tip{position:fixed;pointer-events:none;opacity:0;transition:opacity .1s;background:#26251f;color:#fff;font-size:12.5px;padding:7px 10px;border-radius:7px;box-shadow:0 4px 16px rgba(0,0,0,.3);z-index:50}\n  .callout{background:var(--panel);border:1px solid var(--line);border-left:4px solid var(--bar);border-radius:10px;padding:14px 16px;margin-top:14px;box-shadow:var(--shadow)}\n  .callout b{color:var(--ink)}\n  .callout .hd{font-weight:800;font-size:14px;margin-bottom:4px}\n  .pg{display:flex;gap:22px;flex-wrap:wrap;align-items:center;margin-top:14px;background:linear-gradient(180deg,rgba(94,134,160,.08),transparent);border:1px solid var(--line);border-radius:10px;padding:14px 16px}\n  .pg .num{font-size:22px;font-weight:800;color:var(--accent);font-variant-numeric:tabular-nums}\n  .pg .cap{font-size:13px;color:var(--ink2);max-width:520px}\n  .pg .cap b{color:var(--ink)}\n  .read{font-size:14.5px;color:var(--ink2);margin-top:18px;line-height:1.6;border-left:3px solid var(--bar);padding-left:16px}\n  .read b{color:var(--ink)}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <div class=\"topbar\">\n    <div>\n      <p class=\"kicker\">Common Ground · Immigration plank · the diagnostic</p>\n      <h1>The Backlog: a broken process, not just too few judges</h1>\n      <p class=\"sub\">America's immigration courts hold <b>3.8 million</b> pending cases — up roughly <b>640%</b> since 2016. Over those same years the number of judges more than doubled. The performance measure both sides can read: how many people are stuck, and for how long.</p>\n      <p class=\"src\">Sources: TRAC (Syracuse University), immigration court backlog, 2016–2025. Bipartisan support for the fix: National Common Ground (common-ground.us).</p>\n    </div>\n    <button class=\"toggle\" id=\"themeBtn\">◐ Dark</button>\n  </div>\n\n  <div class=\"tiles\">\n    <div class=\"tile\"><div class=\"lab\">Pending cases (2025)</div><div class=\"big\">3.8 million</div><div class=\"vs\">up from 0.5M in 2016</div></div>\n    <div class=\"tile\"><div class=\"lab\">Cases per judge</div><div class=\"big\">~4,500</div><div class=\"vs\">each — an impossible docket</div></div>\n    <div class=\"tile\"><div class=\"lab\">Average asylum wait</div><div class=\"big\">4.3 yrs</div><div class=\"vs\">years in limbo per case</div></div>\n  </div>\n\n  <div class=\"panel\">\n    <svg id=\"bars\" viewBox=\"0 0 900 440\" role=\"img\" aria-label=\"Immigration court backlog by year, 2016 to 2025\"></svg>\n  </div>\n\n  <div class=\"callout\">\n    <div class=\"hd\">You can't <i>just</i> hire your way out of it.</div>\n    Immigration judges grew from <b>278 (2016)</b> to <b>682 (2023)</b> — up <b>145%</b> — and case closures rose about 30%. Over the same span the backlog grew <b>~640%</b>. More judges help, and they're needed — but headcount alone can't keep up. The <b>process</b> itself has to change too.\n  </div>\n\n  <div class=\"pg\">\n    <div><div class=\"num\">73% · 83%</div></div>\n    <div class=\"cap\"><b>And the fix isn't partisan either.</b> Speeding up case processing — more judges, timelines, and efficient procedures — draws <b>73% of Republicans and 83% of Democrats</b> (National Common Ground). A broken-process problem with a bipartisan answer — <b>the fight is louder than the disagreement.</b></div>\n  </div>\n\n  <p class=\"read\"><b>Reading it.</b> This is the rare immigration fact with no partisan side: a court system so far behind that a case takes four years is failing everyone — the person waiting, the communities involved, and enforcement alike. It shifts the question from <i>who belongs</i> to <i>whether the system works at all</i> — and that's where the real agreement lives.</p>\n</div>\n<div class=\"tip\" id=\"tip\"></div>\n\n<script>\nconst SVGNS='http://www.w3.org/2000/svg';\nconst el=(t,a)=>{const n=document.createElementNS(SVGNS,t);for(const k in a)n.setAttribute(k,a[k]);return n;};\nconst cssv=v=>getComputedStyle(document.body).getPropertyValue(v).trim();\nconst tip=document.getElementById('tip');\nfunction showTip(h,e){tip.innerHTML=h;tip.style.opacity=1;mv(e);}\nfunction mv(e){let x=e.clientX+12,y=e.clientY+12;if(x+170>innerWidth)x=e.clientX-170;tip.style.left=x+'px';tip.style.top=y+'px';}\nfunction hide(){tip.style.opacity=0;}\naddEventListener('mousemove',e=>{if(tip.style.opacity==1)mv(e);});\n\nconst data=[\n {y:'2016',v:0.52},{y:'2018',v:0.81},{y:'2020',v:1.26},{y:'2022',v:1.94},{y:'2023',v:3.08},{y:'2025',v:3.80}\n];\nfunction draw(){\n  const W=900,H=440,m={t:24,r:20,b:46,l:52};\n  const svg=document.getElementById('bars');svg.innerHTML='';\n  const iw=W-m.l-m.r, ih=H-m.t-m.b;\n  const ymax=4;\n  const Y=v=>m.t+ih-(v/ymax)*ih;\n  const grid=cssv('--grid'),muted=cssv('--muted'),bar=cssv('--bar'),ink2=cssv('--ink2');\n  for(let g=0;g<=4;g++){\n    svg.appendChild(el('line',{x1:m.l,x2:m.l+iw,y1:Y(g),y2:Y(g),stroke:grid,'stroke-width':1}));\n    const t=el('text',{x:m.l-9,y:Y(g)+4,'text-anchor':'end',fill:muted,'font-size':11});t.textContent=g+'M';svg.appendChild(t);\n  }\n  const n=data.length, bw=iw/n*0.56, gap=iw/n;\n  data.forEach((d,i)=>{\n    const x=m.l+gap*i+(gap-bw)/2, y=Y(d.v), h=m.t+ih-y;\n    const rect=el('rect',{x:x,y:y,width:bw,height:h,rx:4,fill:bar,'fill-opacity':0.55+0.45*(d.v/ymax)});\n    rect.addEventListener('mousemove',e=>showTip(`<b>${d.y}</b><br>${d.v.toFixed(2)}M pending cases`,e));\n    rect.addEventListener('mouseleave',hide);svg.appendChild(rect);\n    const vt=el('text',{x:x+bw/2,y:y-8,'text-anchor':'middle',fill:bar,'font-size':13,'font-weight':800});\n    vt.textContent=d.v.toFixed(1)+'M';svg.appendChild(vt);\n    const xt=el('text',{x:x+bw/2,y:m.t+ih+20,'text-anchor':'middle',fill:muted,'font-size':12});\n    xt.textContent=d.y;svg.appendChild(xt);\n  });\n  const yl=el('text',{x:16,y:m.t+ih/2,'text-anchor':'middle',fill:ink2,'font-size':12,'font-weight':700,transform:`rotate(-90 16 ${m.t+ih/2})`});\n  yl.textContent='Pending immigration-court cases';svg.appendChild(yl);\n}\ndraw();\nlet rt;addEventListener('resize',()=>{clearTimeout(rt);rt=setTimeout(draw,150);});\ndocument.getElementById('themeBtn').onclick=function(){\n  const h=document.documentElement,dark=h.getAttribute('data-theme')==='dark';\n  h.setAttribute('data-theme',dark?'light':'dark');this.textContent=dark?'◐ Dark':'◑ Light';draw();};\n</script>\n</body>\n</html>\n", "CommonGround_ProductivityPay_v1.html": "<!DOCTYPE html>\n<html lang=\"en\" data-theme=\"light\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Productivity kept climbing. Typical pay didn't.</title>\n<style>\n  :root{\n    --bg:#fcfcfb; --panel:#ffffff; --ink:#26251f; --ink2:#575349; --muted:#8a8578;\n    --line:#e7e3d8; --grid:#efece3;\n    --prod:#5E86A0; --pay:#B98A1F;\n    --shadow:0 1px 2px rgba(40,38,30,.06),0 4px 18px rgba(40,38,30,.06);\n  }\n  html[data-theme=\"dark\"]{\n    --bg:#1a1a19; --panel:#232320; --ink:#eceae2; --ink2:#c3bfb2; --muted:#928d7f;\n    --line:#38372f; --grid:#2c2b25;\n    --prod:#7CA3BD; --pay:#E0C766;\n    --shadow:0 1px 2px rgba(0,0,0,.3),0 4px 20px rgba(0,0,0,.28);\n  }\n  *{box-sizing:border-box}\n  body{margin:0;background:var(--bg);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;line-height:1.5;-webkit-font-smoothing:antialiased}\n  .wrap{max-width:840px;margin:0 auto;padding:34px 24px 70px}\n  h1{font-family:Georgia,serif;font-size:26px;margin:0 0 5px;letter-spacing:-.01em}\n  .kicker{text-transform:uppercase;letter-spacing:.09em;font-size:11px;font-weight:700;color:var(--muted);margin:0 0 4px}\n  .sub{color:var(--ink2);font-size:15px;margin:0;max-width:730px}\n  .src{color:var(--muted);font-size:12px;margin-top:6px}\n  .topbar{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap}\n  .toggle{font-size:12.5px;border:1px solid var(--line);background:var(--panel);color:var(--ink2);border-radius:20px;padding:6px 13px;cursor:pointer}\n  .panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:18px 20px 16px;box-shadow:var(--shadow);margin-top:16px}\n  svg{display:block;width:100%;height:auto;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif}\n  .callout{background:var(--panel);border:1px solid var(--line);border-left:4px solid var(--pay);border-radius:10px;padding:14px 16px;margin-top:14px;box-shadow:var(--shadow);font-size:13.5px;color:var(--ink2);line-height:1.55}\n  .callout b{color:var(--ink)}\n  .callout .hd{font-weight:800;font-size:14px;margin-bottom:4px;color:var(--ink)}\n  .read{font-size:14.5px;color:var(--ink2);margin-top:16px;line-height:1.6;border-left:3px solid var(--prod);padding-left:16px}\n  .read b{color:var(--ink)}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <div class=\"topbar\">\n    <div>\n      <p class=\"kicker\">Common Ground · the problem under An Honest System</p>\n      <h1>Productivity kept climbing. Typical pay didn't.</h1>\n      <p class=\"sub\">For the three decades after World War II, a typical worker's pay rose right along with the economy's output per hour of work. Since the late 1970s the two have split — productivity has grown almost <b>four times</b> as much as pay.</p>\n      <p class=\"src\">Source: Economic Policy Institute, net productivity vs. a typical worker's compensation, indexed to 1948. A measure of the problem — not, by itself, a prescription.</p>\n    </div>\n    <button class=\"toggle\" id=\"themeBtn\">◐ Dark</button>\n  </div>\n\n  <div class=\"panel\">\n    <svg id=\"chart\" viewBox=\"0 0 820 420\" role=\"img\" aria-label=\"Cumulative growth in productivity versus typical worker pay, 1948 to 2019, showing them rising together until 1979 then diverging\"></svg>\n  </div>\n\n  <div class=\"callout\">\n    <div class=\"hd\">What broke the link</div>\n    The gap sizes the problem, but doesn't by itself name the cause — and economists debate the mix. Most point to a shift in <b>the rules and in bargaining power</b>: weaker unions, a minimum wage left to erode, rising employer concentration, and lighter enforcement, alongside globalization and technology. The through-line is <b>leverage</b>, not that any one company underpays — which is why the fixes are <b>rules-based</b> (more competition, a real wage floor, stronger enforcement), and pointedly <b>not</b> government setting anyone's paycheck.\n  </div>\n\n  <p class=\"read\"><b>Reading it.</b> For the three decades after WWII, pay and productivity rose together — work and reward were linked. Then, over the years that followed, they split apart: the economy kept producing more per hour, and a typical worker's pay stopped keeping up. That's the broken bargain in a single picture. It's a fairness problem of the plainest kind — the reward was earned — which is why it reads across party lines, where \"the rich have too much\" does not.</p>\n</div>\n\n<script>\nconst SVGNS='http://www.w3.org/2000/svg';\nconst el=(t,a)=>{const n=document.createElementNS(SVGNS,t);for(const k in a)n.setAttribute(k,a[k]);return n;};\nconst cssv=v=>getComputedStyle(document.body).getPropertyValue(v).trim();\n// Cumulative % growth since 1948 (index 1948=0). EPI series: net productivity vs. typical worker compensation.\nconst yrs =[1948,1960,1973,1979,1990,2000,2010,2019];\nconst prod=[0,   48,  97,  112, 140, 183, 220, 239];\nconst pay =[0,   45,  89,  90,  94,  108, 114, 120];\nfunction draw(){\n  const W=820,H=420,m={t:26,r:120,b:44,l:52};\n  const svg=document.getElementById('chart');svg.innerHTML='';\n  const iw=W-m.l-m.r, ih=H-m.t-m.b, ymax=260, x0=1948, x1=2019;\n  const X=y=>m.l+ (y-x0)/(x1-x0)*iw;\n  const Y=v=>m.t+ih-(v/ymax)*ih;\n  const grid=cssv('--grid'),muted=cssv('--muted'),ink2=cssv('--ink2'),prodc=cssv('--prod'),payc=cssv('--pay'),line=cssv('--line');\n  // y gridlines\n  for(let g=0;g<=250;g+=50){\n    svg.appendChild(el('line',{x1:m.l,x2:m.l+iw,y1:Y(g),y2:Y(g),stroke:grid,'stroke-width':1}));\n    const t=el('text',{x:m.l-9,y:Y(g)+4,'text-anchor':'end',fill:muted,'font-size':11});t.textContent='+'+g+'%';svg.appendChild(t);\n  }\n  // x year labels (clean decades)\n  [1950,1960,1980,2000,2019].forEach(y=>{\n    const t=el('text',{x:X(y),y:m.t+ih+20,'text-anchor':'middle',fill:muted,'font-size':11});t.textContent=(y===2019?2020:y);svg.appendChild(t);\n  });\n  // path builder\n  const path=arr=>arr.map((v,i)=>(i?'L':'M')+X(yrs[i]).toFixed(1)+' '+Y(v).toFixed(1)).join(' ');\n  svg.appendChild(el('path',{d:path(pay),fill:'none',stroke:payc,'stroke-width':3,'stroke-linejoin':'round','stroke-linecap':'round'}));\n  svg.appendChild(el('path',{d:path(prod),fill:'none',stroke:prodc,'stroke-width':3,'stroke-linejoin':'round','stroke-linecap':'round'}));\n  // end labels\n  const lp=el('text',{x:m.l+iw+8,y:Y(prod[prod.length-1])+4,fill:prodc,'font-size':12.5,'font-weight':800});lp.textContent='Productivity';svg.appendChild(lp);\n  const lp2=el('text',{x:m.l+iw+8,y:Y(prod[prod.length-1])+20,fill:prodc,'font-size':11});lp2.textContent='+239%';svg.appendChild(lp2);\n  const ly=el('text',{x:m.l+iw+8,y:Y(pay[pay.length-1])+4,fill:payc,'font-size':12.5,'font-weight':800});ly.textContent='Typical pay';svg.appendChild(ly);\n  const ly2=el('text',{x:m.l+iw+8,y:Y(pay[pay.length-1])+20,fill:payc,'font-size':11});ly2.textContent='+120%';svg.appendChild(ly2);\n  // y axis title\n  const yl=el('text',{x:14,y:m.t+ih/2,'text-anchor':'middle',fill:ink2,'font-size':11.5,'font-weight':700,transform:`rotate(-90 14 ${m.t+ih/2})`});yl.textContent='Cumulative growth since 1948';svg.appendChild(yl);\n}\ndraw();\nlet rt;addEventListener('resize',()=>{clearTimeout(rt);rt=setTimeout(draw,150);});\ndocument.getElementById('themeBtn').onclick=function(){\n  const h=document.documentElement,dark=h.getAttribute('data-theme')==='dark';\n  h.setAttribute('data-theme',dark?'light':'dark');this.textContent=dark?'◐ Dark':'◑ Light';draw();};\n</script>\n</body>\n</html>\n", "CommonGround_GunDangerousAccess_v1.html": "<!DOCTYPE html>\n<html lang=\"en\" data-theme=\"light\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Gun Safety — the problem, measured</title>\n<style>\n  :root{\n    --bg:#faf8f3; --panel:#fffdf8; --ink:#2b2622; --ink2:#4a433c; --muted:#8a8178;\n    --line:#e7e0d4; --grid:#efe9dd; --shadow:0 1px 3px rgba(0,0,0,.06);\n    --gun:#A85A6B; --gun-tint:#f5eaed; --self:#B07A3C; --other:#6E7378; --oth2:#c9b8a0;\n    --good:#3f9184; --warn:#C6972F; --bad:#b45a4e;\n  }\n  html[data-theme=\"dark\"]{\n    --bg:#1c1917; --panel:#242019; --ink:#f0e9dd; --ink2:#c9c0b2; --muted:#9a9084;\n    --line:#3a342b; --grid:#2f2a22; --shadow:none;\n    --gun:#cf8b98; --self:#CE9B54; --other:#9AA0A6; --oth2:#b7a389;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;background:var(--bg);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,sans-serif;line-height:1.5;padding:28px 22px 40px}\n  .wrap{max-width:820px;margin:0 auto}\n  .kicker{font-size:12px;text-transform:uppercase;letter-spacing:.09em;color:var(--gun);font-weight:800;margin:0 0 4px}\n  h1{font-family:Georgia,\"Times New Roman\",serif;font-size:25px;margin:0 0 4px;font-weight:700}\n  .sub{font-size:13.5px;color:var(--ink2);margin:0 0 22px;max-width:640px}\n  .card{background:var(--panel);border:1px solid var(--line);border-radius:13px;box-shadow:var(--shadow);padding:20px 22px;margin:0 0 20px}\n  .card h2{font-size:15px;margin:0 0 3px;font-weight:800}\n  .card .cx{font-size:12.5px;color:var(--muted);margin:0 0 16px}\n  /* stacked composition bar */\n  .stack{display:flex;height:52px;border-radius:8px;overflow:hidden;border:1px solid var(--line)}\n  .seg{display:flex;flex-direction:column;justify-content:center;padding:0 12px;color:#fff}\n  .seg b{font-size:19px;line-height:1;font-weight:800}\n  .seg span{font-size:10.5px;opacity:.95;margin-top:3px;font-weight:600;letter-spacing:.02em}\n  .legend{display:flex;gap:20px;flex-wrap:wrap;margin-top:13px;font-size:12.5px;color:var(--ink2)}\n  .legend .k{display:flex;gap:7px;align-items:flex-start}\n  .legend .sw{width:11px;height:11px;border-radius:3px;margin-top:3px;flex:none}\n  .legend b{font-variant-numeric:tabular-nums}\n  .note{font-size:12.5px;color:var(--ink2);margin-top:15px;line-height:1.5;border-top:1px solid var(--grid);padding-top:12px}\n  /* cliff bars */\n  .cliff{margin-top:6px}\n  .row{display:grid;grid-template-columns:200px 1fr 44px;align-items:center;gap:12px;margin:9px 0}\n  .row .lab{font-size:12.5px;color:var(--ink);text-align:right}\n  .row .lab small{display:block;color:var(--muted);font-size:10.5px}\n  .track{background:var(--grid);border-radius:5px;height:20px;overflow:hidden}\n  .fill{height:100%;border-radius:5px;display:block}\n  .row .pct{font-size:13px;font-weight:800;font-variant-numeric:tabular-nums;text-align:right}\n  .foot{font-size:11px;color:var(--muted);margin-top:8px;line-height:1.5}\n  .toggle{position:fixed;top:14px;right:16px;font-size:12px;border:1px solid var(--line);background:var(--panel);color:var(--ink2);border-radius:20px;padding:5px 12px;cursor:pointer}\n</style>\n</head>\n<body>\n<button class=\"toggle\" id=\"t\">◐ Dark</button>\n<div class=\"wrap\">\n  <p class=\"kicker\">Gun Safety · the problem, measured</p>\n  <h1>Dangerous access — where the danger actually is</h1>\n  <p class=\"sub\">The agreed-upon problem isn't guns, and it isn't law-abiding owners. It's guns reaching people who are a danger — to others, or to themselves. Here's where that danger concentrates, and where the agreement holds.</p>\n\n  <div class=\"card\">\n    <h2>Where the danger is</h2>\n    <p class=\"cx\">US firearm deaths, 2023 — 46,728 total (CDC / Johns Hopkins Center for Gun Violence Solutions)</p>\n    <div class=\"stack\">\n      <div class=\"seg\" style=\"width:58%;background:var(--self)\"><b>58%</b><span>DANGER TO SELF</span></div>\n      <div class=\"seg\" style=\"width:38%;background:var(--other)\"><b>38%</b><span>DANGER TO OTHERS</span></div>\n      <div class=\"seg\" style=\"width:4%;background:var(--oth2);color:#3b332a\"><b></b><span></span></div>\n    </div>\n    <div class=\"legend\">\n      <div class=\"k\"><span class=\"sw\" style=\"background:var(--self)\"></span><div><b>Suicide — 27,300</b> (58%). People in crisis. Red-flag laws, safe storage, and waiting periods aim here.</div></div>\n      <div class=\"k\"><span class=\"sw\" style=\"background:var(--other)\"></span><div><b>Homicide — 17,927</b> (38%). Interpersonal violence, heavily domestic. Background checks and the domestic-violence restriction aim here.</div></div>\n      <div class=\"k\"><span class=\"sw\" style=\"background:var(--oth2)\"></span><div><b>Other — ~1,500</b> (accidental, undetermined).</div></div>\n    </div>\n    <p class=\"note\">The debate is dominated by mass shootings and gun bans — but the danger is overwhelmingly <b>people in crisis</b> and <b>interpersonal violence</b>. The bulk is <b>danger to self</b>, the part talked about least. Every Platform policy is built to interrupt exactly these channels. <span style=\"color:var(--muted)\">(An abuser's access to a gun makes intimate-partner homicide about <b>5× more likely</b> — Campbell et al., 2003.)</span></p>\n  </div>\n\n  <div class=\"card\">\n    <h2>The cliff — where agreement ends</h2>\n    <p class=\"cx\">Republican support, by policy — the drop comes at the product line, not before</p>\n    <div class=\"cliff\">\n      <div class=\"row\"><div class=\"lab\">Background checks<small>keep guns from prohibited buyers</small></div><div class=\"track\"><i class=\"fill\" style=\"width:70%;background:var(--good)\"></i></div><div class=\"pct\" style=\"color:var(--good)\">70</div></div>\n      <div class=\"row\"><div class=\"lab\">Red-flag laws<small>temporary removal in a crisis</small></div><div class=\"track\"><i class=\"fill\" style=\"width:66%;background:var(--good)\"></i></div><div class=\"pct\" style=\"color:var(--good)\">66</div></div>\n      <div class=\"row\"><div class=\"lab\">Assault-weapons ban<small>banning a category of gun</small></div><div class=\"track\"><i class=\"fill\" style=\"width:27%;background:var(--bad)\"></i></div><div class=\"pct\" style=\"color:var(--bad)\">27</div></div>\n    </div>\n    <p class=\"note\">Republicans back keeping guns from dangerous people — the <b>process</b> (who can get one, and stepping in during a crisis). Support falls off a cliff only at the <b>product</b> question: banning specific guns. The agreement is everything to the left of the cliff; the fight lives on its edge — and the fight is louder than the disagreement.</p>\n    <p class=\"foot\">Support: background checks — Pew 2021 (70% R); red-flag — Johns Hopkins 2025 (66% R); assault-weapons ban — Gallup 2024 (27% R). Death composition — CDC WONDER / Johns Hopkins Center for Gun Violence Solutions, 2023.</p>\n  </div>\n</div>\n<script>\n  document.getElementById('t').onclick=function(){\n    const h=document.documentElement,d=h.getAttribute('data-theme')==='dark';\n    h.setAttribute('data-theme',d?'light':'dark');this.textContent=d?'◐ Dark':'◑ Light';};\n</script>\n</body>\n</html>\n", "CommonGround_MobilityDecline_v1.html": "<!DOCTYPE html>\n<html lang=\"en\" data-theme=\"light\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Opportunity — the problem, measured</title>\n<style>\n  :root{\n    --bg:#faf8f3; --panel:#fffdf8; --ink:#2b2622; --ink2:#4a433c; --muted:#8a8178;\n    --line:#e7e0d4; --grid:#efe9dd; --shadow:0 1px 3px rgba(0,0,0,.06);\n    --accent:#B07A3C; --good:#3f9184; --bad:#b45a4e; --hi:#C0803A;\n  }\n  html[data-theme=\"dark\"]{\n    --bg:#1c1917; --panel:#242019; --ink:#f0e9dd; --ink2:#c9c0b2; --muted:#9a9084;\n    --line:#3a342b; --grid:#2f2a22; --shadow:none; --accent:#d3a860; --hi:#d3a860;\n  }\n  *{box-sizing:border-box}\n  body{margin:0;background:var(--bg);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,sans-serif;line-height:1.5;padding:26px 22px 34px}\n  .wrap{max-width:820px;margin:0 auto}\n  .kicker{font-size:12px;text-transform:uppercase;letter-spacing:.09em;color:var(--accent);font-weight:800;margin:0 0 4px}\n  h1{font-family:Georgia,\"Times New Roman\",serif;font-size:24px;margin:0 0 4px;font-weight:700}\n  .sub{font-size:13.5px;color:var(--ink2);margin:0 0 20px;max-width:660px}\n  .card{background:var(--panel);border:1px solid var(--line);border-radius:13px;box-shadow:var(--shadow);padding:18px 20px;margin:0 0 18px}\n  .card h2{font-size:15px;margin:0 0 3px;font-weight:800}\n  .card .cx{font-size:12.5px;color:var(--muted);margin:0 0 18px}\n  .bars{display:flex;align-items:flex-end;gap:16px;height:230px;padding:0 4px;border-bottom:2px solid var(--line)}\n  .bcol{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%}\n  .bval{font-size:15px;font-weight:800;margin-bottom:5px;font-variant-numeric:tabular-nums}\n  .bar{width:100%;max-width:70px;border-radius:6px 6px 0 0;background:var(--hi)}\n  .blab{font-size:11.5px;color:var(--muted);margin-top:8px;text-align:center}\n  .blab b{display:block;color:var(--ink2);font-size:12px}\n  .note{font-size:12.5px;color:var(--ink2);margin-top:16px;line-height:1.55;border-top:1px solid var(--grid);padding-top:12px}\n  .foot{font-size:11px;color:var(--muted);margin-top:8px;line-height:1.5}\n  .toggle{position:fixed;top:14px;right:16px;font-size:12px;border:1px solid var(--line);background:var(--panel);color:var(--ink2);border-radius:20px;padding:5px 12px;cursor:pointer}\n</style>\n</head>\n<body>\n<button class=\"toggle\" id=\"t\">◐ Dark</button>\n<div class=\"wrap\">\n  <p class=\"kicker\">Opportunity &amp; Self-Reliance · the problem, measured</p>\n  <h1>The fading American Dream</h1>\n  <p class=\"sub\">Self-reliance is motivated by seeing a real chance to get ahead. That chance is measured by <b>absolute mobility</b> — the share of children who grow up to out-earn their parents. It has fallen from near-certain to a coin flip.</p>\n  <div class=\"card\">\n    <h2>Share of children who out-earn their parents, by birth year</h2>\n    <p class=\"cx\">Measured at age 30, adjusted for inflation (Chetty et al., Opportunity Insights)</p>\n    <div class=\"bars\">\n      <div class=\"bcol\"><div class=\"bval\" style=\"color:var(--good)\">92%</div><div class=\"bar\" style=\"height:92%;background:var(--good)\"></div><div class=\"blab\"><b>1940</b>born</div></div>\n      <div class=\"bcol\"><div class=\"bval\">79%</div><div class=\"bar\" style=\"height:79%\"></div><div class=\"blab\"><b>1950</b>born</div></div>\n      <div class=\"bcol\"><div class=\"bval\">62%</div><div class=\"bar\" style=\"height:62%\"></div><div class=\"blab\"><b>1960</b>born</div></div>\n      <div class=\"bcol\"><div class=\"bval\">61%</div><div class=\"bar\" style=\"height:61%\"></div><div class=\"blab\"><b>1970</b>born</div></div>\n      <div class=\"bcol\"><div class=\"bval\" style=\"color:var(--bad)\">50%</div><div class=\"bar\" style=\"height:50%;background:var(--bad)\"></div><div class=\"blab\"><b>1980</b>born</div></div>\n    </div>\n    <p class=\"note\">A child born in 1940 was almost certain — <b>92%</b> — to earn more than their parents. A child born in 1980 faces a <b>coin flip</b>. This is the problem the plank addresses: not envy of the top, but the collapse of the ladder itself. Invest in people so the odds of getting ahead climb back — the conservative case for opportunity, framed as <b>self-reliance, not dependency.</b></p>\n    <p class=\"foot\">Source: Raj Chetty et al., \"The Fading American Dream,\" Opportunity Insights / Science, 2017. Absolute income mobility at age 30.</p>\n  </div>\n</div>\n<script>\n  document.getElementById('t').onclick=function(){const h=document.documentElement,d=h.getAttribute('data-theme')==='dark';h.setAttribute('data-theme',d?'light':'dark');this.textContent=d?'◐ Dark':'◑ Light';};\n</script>\n</body>\n</html>\n", "CommonGround_ElectionTrust_v1.html": "<!DOCTYPE html>\n<html lang=\"en\" data-theme=\"light\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Trust in elections now depends on who won</title>\n<style>\n  :root{\n    --bg:#fcfcfb; --panel:#ffffff; --ink:#26251f; --ink2:#575349; --muted:#8a8578;\n    --line:#e7e3d8; --grid:#efece3;\n    --rep:#C0483F; --dem:#5E86A0;\n    --shadow:0 1px 2px rgba(40,38,30,.06),0 4px 18px rgba(40,38,30,.06);\n  }\n  html[data-theme=\"dark\"]{\n    --bg:#1a1a19; --panel:#232320; --ink:#eceae2; --ink2:#c3bfb2; --muted:#928d7f;\n    --line:#38372f; --grid:#2c2b25;\n    --rep:#E07A72; --dem:#7CA3BD;\n    --shadow:0 1px 2px rgba(0,0,0,.3),0 4px 20px rgba(0,0,0,.28);\n  }\n  *{box-sizing:border-box}\n  body{margin:0;background:var(--bg);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;line-height:1.5;-webkit-font-smoothing:antialiased}\n  .wrap{max-width:840px;margin:0 auto;padding:34px 24px 70px}\n  h1{font-family:Georgia,serif;font-size:26px;margin:0 0 5px;letter-spacing:-.01em}\n  .kicker{text-transform:uppercase;letter-spacing:.09em;font-size:11px;font-weight:700;color:var(--muted);margin:0 0 4px}\n  .sub{color:var(--ink2);font-size:15px;margin:0;max-width:740px}\n  .src{color:var(--muted);font-size:12px;margin-top:6px}\n  .topbar{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap}\n  .toggle{font-size:12.5px;border:1px solid var(--line);background:var(--panel);color:var(--ink2);border-radius:20px;padding:6px 13px;cursor:pointer}\n  .panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:18px 20px 14px;box-shadow:var(--shadow);margin-top:16px}\n  .panel h2{font-size:15px;margin:0 0 3px;font-family:Georgia,serif}\n  .panel .psub{font-size:12.5px;color:var(--muted);margin:0 0 6px}\n  svg{display:block;width:100%;height:auto;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif}\n  .callout{background:var(--panel);border:1px solid var(--line);border-left:4px solid var(--rep);border-radius:10px;padding:14px 16px;margin-top:14px;box-shadow:var(--shadow);font-size:13.5px;color:var(--ink2);line-height:1.55}\n  .callout b{color:var(--ink)}\n  .callout .hd{font-weight:800;font-size:14px;margin-bottom:4px;color:var(--ink)}\n  .reality{background:var(--panel);border:1px solid var(--line);border-left:4px solid #3E7D5A;border-radius:10px;padding:14px 16px;margin-top:14px;box-shadow:var(--shadow);font-size:13.5px;color:var(--ink2);line-height:1.55}\n  html[data-theme=\"dark\"] .reality{border-left-color:#5FA57C}\n  .reality b{color:var(--ink)}\n  .reality .hd{font-weight:800;font-size:14px;margin-bottom:4px;color:var(--ink)}\n  .read{font-size:14.5px;color:var(--ink2);margin-top:16px;line-height:1.6;border-left:3px solid var(--dem);padding-left:16px}\n  .read b{color:var(--ink)}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <div class=\"topbar\">\n    <div>\n      <p class=\"kicker\">Common Ground · Secure &amp; Fair Elections · the problem, measured</p>\n      <h1>Trust in elections now depends on who won</h1>\n      <p class=\"sub\">Fewer than <b>6 in 10</b> Americans are confident their votes are counted accurately — down from about two-thirds a decade ago. And confidence swings with the result: take the 2024 election — <b>same votes, same count</b>, but faith in it flipped depending on which side won.</p>\n      <p class=\"src\">Main chart: AP-NORC, confidence votes were counted accurately nationally (Oct 2024 vs Dec 2024). Trend &amp; partisan gap: Gallup, 2016–2024.</p>\n    </div>\n    <button class=\"toggle\" id=\"themeBtn\">◐ Dark</button>\n  </div>\n\n  <div class=\"panel\">\n    <h2>Same election, same count — confidence flipped with the result</h2>\n    <p class=\"psub\">Share confident the 2024 votes were counted accurately nationwide</p>\n    <svg id=\"slope\" viewBox=\"0 0 780 360\" role=\"img\" aria-label=\"Republican confidence rose from 20 to 60 percent after Trump won 2024, while Democratic confidence fell from 70 to 60 percent\"></svg>\n  </div>\n\n  <div class=\"reality\">\n    <div class=\"hd\">The doubt isn't tracking reality</div>\n    The fraud all this fear is about is <b>vanishingly rare</b> — and not just by liberal accounting. The Brennan Center puts the rate between <b>0.0003% and 0.0025%</b> of ballots (you're likelier to be struck by lightning than to impersonate a voter). Even the <b>Heritage Foundation's own</b> fraud database — built to catalogue every case it can find — lists on the order of <b>1,500</b> over decades, against <b>billions</b> of votes. And the Trump administration's <b>own</b> voter-fraud commission disbanded in 2018 without finding evidence of widespread fraud. Trust swings 40 points from one election to the next; the fraud rate never leaves the floor.\n  </div>\n\n  <div class=\"callout\">\n    <div class=\"hd\">Why this is the problem</div>\n    Confidence is tracking <b>who won</b>, not whether the count was accurate — the votes didn't change between October and December, only the winner did. When faith in elections rises and falls with the result, <b>no outcome is broadly accepted</b>, and each election's losers are left doubting the system. You can't fix that by convincing people their side lost fairly. You fix it with <b>rules both sides trust before they know who wins</b> — photo ID, a paper trail that can be audited, verified results.\n  </div>\n\n  <p class=\"read\"><b>Reading it.</b> This is why the plank runs on <b>mechanics</b>, not on the outcome fight. The nuts and bolts of running an election are exactly where agreement already exists across both parties — photo ID (95% of Republicans, 71% of Democrats), paper-ballot backups (87 / 82), time to vote. Those are the rules people accept <i>in advance</i>, regardless of who they expect to win — which is what rebuilds trust that lasts past one election night.</p>\n</div>\n\n<script>\nconst SVGNS='http://www.w3.org/2000/svg';\nconst el=(t,a)=>{const n=document.createElementNS(SVGNS,t);for(const k in a)n.setAttribute(k,a[k]);return n;};\nconst cssv=v=>getComputedStyle(document.body).getPropertyValue(v).trim();\nconst series=[\n {k:'Republicans', c:'--rep', before:20, after:60},\n {k:'Democrats',   c:'--dem', before:70, after:60}\n];\nfunction draw(){\n  const W=780,H=360,m={t:30,r:150,b:52,l:52};\n  const svg=document.getElementById('slope');svg.innerHTML='';\n  const iw=W-m.l-m.r, ih=H-m.t-m.b, ymax=100;\n  const xB=m.l+iw*0.12, xA=m.l+iw*0.88;\n  const Y=v=>m.t+ih-(v/ymax)*ih;\n  const grid=cssv('--grid'),muted=cssv('--muted'),ink2=cssv('--ink2');\n  for(let g=0;g<=100;g+=25){\n    svg.appendChild(el('line',{x1:m.l,x2:m.l+iw,y1:Y(g),y2:Y(g),stroke:grid,'stroke-width':1}));\n    const t=el('text',{x:m.l-9,y:Y(g)+4,'text-anchor':'end',fill:muted,'font-size':11});t.textContent=g+'%';svg.appendChild(t);\n  }\n  // x labels\n  const xl1=el('text',{x:xB,y:m.t+ih+24,'text-anchor':'middle',fill:ink2,'font-size':12.5,'font-weight':700});xl1.textContent='Before the 2024 vote';svg.appendChild(xl1);\n  const xl2=el('text',{x:xA,y:m.t+ih+24,'text-anchor':'middle',fill:ink2,'font-size':12.5,'font-weight':700});xl2.textContent='After Trump won';svg.appendChild(xl2);\n  const xl1b=el('text',{x:xB,y:m.t+ih+40,'text-anchor':'middle',fill:muted,'font-size':10.5});xl1b.textContent='(October)';svg.appendChild(xl1b);\n  const xl2b=el('text',{x:xA,y:m.t+ih+40,'text-anchor':'middle',fill:muted,'font-size':10.5});xl2b.textContent='(December)';svg.appendChild(xl2b);\n  series.forEach(s=>{\n    const col=cssv(s.c);\n    const isRep=s.k==='Republicans';\n    svg.appendChild(el('line',{x1:xB,y1:Y(s.before),x2:xA,y2:Y(s.after),stroke:col,'stroke-width':3.5,'stroke-linecap':'round'}));\n    // before point + value (above)\n    svg.appendChild(el('circle',{cx:xB,cy:Y(s.before),r:5.5,fill:col}));\n    const tb=el('text',{x:xB,y:Y(s.before)-12,'text-anchor':'middle',fill:col,'font-size':15,'font-weight':800});tb.textContent=s.before+'%';svg.appendChild(tb);\n    // after point + value (staggered so the two lines' end labels don't collide)\n    svg.appendChild(el('circle',{cx:xA,cy:Y(s.after),r:5.5,fill:col}));\n    const ta=el('text',{x:xA,y:Y(s.after)+(isRep?24:-12),'text-anchor':'middle',fill:col,'font-size':15,'font-weight':800});ta.textContent=s.after+'%';svg.appendChild(ta);\n    const lab=el('text',{x:xA+12,y:Y(s.after)+(isRep?16:-4),fill:col,'font-size':13.5,'font-weight':800});lab.textContent=s.k;svg.appendChild(lab);\n  });\n}\ndraw();\nlet rt;addEventListener('resize',()=>{clearTimeout(rt);rt=setTimeout(draw,150);});\ndocument.getElementById('themeBtn').onclick=function(){\n  const h=document.documentElement,dark=h.getAttribute('data-theme')==='dark';\n  h.setAttribute('data-theme',dark?'light':'dark');this.textContent=dark?'◐ Dark':'◑ Light';draw();};\n</script>\n</body>\n</html>\n", "CommonGround_EnvStakes_v1.html": "<!DOCTYPE html>\n<html lang=\"en\" data-theme=\"light\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Four goals we share — clean air, nature, resilience, energy security</title>\n<style>\n  :root{\n    --bg:#fcfcfb; --panel:#ffffff; --ink:#26251f; --ink2:#575349; --muted:#8a8578;\n    --line:#e7e3d8; --grid:#efece3;\n    --ben:#3E7D5A; --cost:#B98A1F; --accent:#5E86A0;\n    --shadow:0 1px 2px rgba(40,38,30,.06),0 4px 18px rgba(40,38,30,.06);\n  }\n  html[data-theme=\"dark\"]{\n    --bg:#1a1a19; --panel:#232320; --ink:#eceae2; --ink2:#c3bfb2; --muted:#928d7f;\n    --line:#38372f; --grid:#2c2b25;\n    --ben:#5FA57C; --cost:#E0C766; --accent:#7CA3BD;\n    --shadow:0 1px 2px rgba(0,0,0,.3),0 4px 20px rgba(0,0,0,.28);\n  }\n  *{box-sizing:border-box}\n  body{margin:0;background:var(--bg);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;line-height:1.5;-webkit-font-smoothing:antialiased}\n  .wrap{max-width:940px;margin:0 auto;padding:34px 24px 70px}\n  h1{font-family:Georgia,serif;font-size:26px;margin:0 0 5px;letter-spacing:-.01em}\n  .kicker{text-transform:uppercase;letter-spacing:.09em;font-size:11px;font-weight:700;color:var(--muted);margin:0 0 4px}\n  .sub{color:var(--ink2);font-size:15px;margin:0;max-width:780px}\n  .src{color:var(--muted);font-size:12px;margin-top:6px}\n  .topbar{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap}\n  .toggle{font-size:12.5px;border:1px solid var(--line);background:var(--panel);color:var(--ink2);border-radius:20px;padding:6px 13px;cursor:pointer}\n  .tiles{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:22px 0 8px}\n  @media(max-width:720px){.tiles{grid-template-columns:repeat(2,1fr)}}\n  .tile{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px 15px;box-shadow:var(--shadow)}\n  .tile .lab{font-size:11.5px;color:var(--muted);font-weight:700;text-transform:uppercase;letter-spacing:.04em}\n  .tile .big{font-size:23px;font-weight:800;margin:7px 0 3px;font-variant-numeric:tabular-nums;color:var(--accent);line-height:1.05}\n  .tile .vs{font-size:12px;color:var(--ink2);line-height:1.4}\n  .panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:18px 20px 14px;box-shadow:var(--shadow);margin-top:12px}\n  .panel h2{font-size:15px;margin:0 0 2px;font-family:Georgia,serif}\n  .panel .psub{font-size:12.5px;color:var(--muted);margin:0 0 6px}\n  svg{display:block;width:100%;height:auto;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif}\n  .callout{background:var(--panel);border:1px solid var(--line);border-left:4px solid var(--ben);border-radius:10px;padding:14px 16px;margin-top:14px;box-shadow:var(--shadow);font-size:13.5px;color:var(--ink2);line-height:1.55}\n  .callout b{color:var(--ink)}\n  .callout .hd{font-weight:800;font-size:14px;margin-bottom:4px;color:var(--ink)}\n  .read{font-size:14.5px;color:var(--ink2);margin-top:18px;line-height:1.6;border-left:3px solid var(--accent);padding-left:16px}\n  .read b{color:var(--ink)}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <div class=\"topbar\">\n    <div>\n      <p class=\"kicker\">Common Ground · Environment &amp; Energy · the problem, measured</p>\n      <h1>Four goals we share — even when we fight over the causes</h1>\n      <p class=\"sub\">What this plank protects: the air we breathe, the nature we pass on, our resilience to costly disasters, and our energy security. You don't have to agree on climate science to agree these are worth having.</p>\n      <p class=\"src\">Sources: EPA, Benefits &amp; Costs of the Clean Air Act 1990–2020; NOAA/NCEI billion-dollar disasters (through 2024); BEA outdoor-recreation economy (2024); EIA energy trade.</p>\n    </div>\n    <button class=\"toggle\" id=\"themeBtn\">◐ Dark</button>\n  </div>\n\n  <div class=\"tiles\">\n    <div class=\"tile\"><div class=\"lab\">Clean air · health</div><div class=\"big\">230,000</div><div class=\"vs\">early deaths prevented every year by the Clean Air Act — benefits over 30× its cost</div></div>\n    <div class=\"tile\"><div class=\"lab\">Conservation</div><div class=\"big\">$1.2 trillion</div><div class=\"vs\">outdoor-recreation economy · ~5 million jobs — the value of nature kept</div></div>\n    <div class=\"tile\"><div class=\"lab\">Disaster resilience</div><div class=\"big\">~$149B / yr</div><div class=\"vs\">cost of billion-dollar disasters (2020–24) — about double the long-run average</div></div>\n    <div class=\"tile\"><div class=\"lab\">Energy security</div><div class=\"big\">Net exporter</div><div class=\"vs\">US energy: a net exporter since 2019 — first time since 1952</div></div>\n  </div>\n\n  <div class=\"panel\">\n    <h2>Cleaning the air paid for itself many times over</h2>\n    <p class=\"psub\">Clean Air Act, 1990–2020 — benefits vs. costs (EPA central estimate)</p>\n    <svg id=\"bars\" viewBox=\"0 0 780 300\" role=\"img\" aria-label=\"Clean Air Act benefits exceed costs by more than thirty to one\"></svg>\n  </div>\n\n  <div class=\"callout\">\n    <div class=\"hd\">Agree on the goals — the fight is over causes and cures.</div>\n    Americans broadly want all four: cleaner air, protected lands and waters, resilience to costly disasters, and secure, affordable energy. Where we divide is over <b>what's causing the harm</b> (the man-made-climate debate) and <b>which remedies to use</b> (the “mandate” fight — a carbon tax, fossil-fuel bans, EV mandates). But <b>you don't have to settle the cause to share the goal</b> — and when remedies are described concretely rather than as slogans, even those clear both parties.\n  </div>\n\n  <p class=\"read\"><b>Reading it.</b> This plank protects four things at once — the air we breathe, the nature we pass on, the rising bill for disasters, and our energy security. None of them requires agreeing on climate science: clean air saves lives whatever you believe about CO₂, public lands are worth keeping, disasters are expensive to absorb, and energy security is national security. The goals, we share; the argument is about causes and cures.</p>\n</div>\n<div class=\"tip\" id=\"tip\"></div>\n\n<script>\nconst SVGNS='http://www.w3.org/2000/svg';\nconst el=(t,a)=>{const n=document.createElementNS(SVGNS,t);for(const k in a)n.setAttribute(k,a[k]);return n;};\nconst cssv=v=>getComputedStyle(document.body).getPropertyValue(v).trim();\n// Ratio-based: costs = 1 unit, benefits > 30 units (EPA: benefits exceed costs by more than 30 to 1)\nconst data=[{k:'Costs',v:1,c:'--cost',s:'pollution-control spending'},{k:'Benefits',v:30,c:'--ben',s:'health & economic gains'}];\nfunction draw(){\n  const W=780,H=300,m={t:26,r:24,b:52,l:60};\n  const svg=document.getElementById('bars');svg.innerHTML='';\n  const iw=W-m.l-m.r, ih=H-m.t-m.b, ymax=32;\n  const Y=v=>m.t+ih-(v/ymax)*ih;\n  const grid=cssv('--grid'),muted=cssv('--muted'),ink2=cssv('--ink2');\n  for(let g=0;g<=30;g+=10){\n    svg.appendChild(el('line',{x1:m.l,x2:m.l+iw,y1:Y(g),y2:Y(g),stroke:grid,'stroke-width':1}));\n    const t=el('text',{x:m.l-9,y:Y(g)+4,'text-anchor':'end',fill:muted,'font-size':11});t.textContent='$'+g;svg.appendChild(t);\n  }\n  const n=data.length,gap=iw/n,bw=Math.min(150,gap*0.46);\n  data.forEach((d,i)=>{\n    const x=m.l+gap*i+(gap-bw)/2,y=Y(d.v),h=m.t+ih-y,col=cssv(d.c);\n    svg.appendChild(el('rect',{x,y,width:bw,height:h,rx:5,fill:col}));\n    const vt=el('text',{x:x+bw/2,y:y-10,'text-anchor':'middle',fill:col,'font-size':19,'font-weight':800});\n    vt.textContent = d.k==='Costs' ? '$1' : 'over $30';svg.appendChild(vt);\n    const kt=el('text',{x:x+bw/2,y:m.t+ih+22,'text-anchor':'middle',fill:ink2,'font-size':13,'font-weight':700});kt.textContent=d.k;svg.appendChild(kt);\n    const st=el('text',{x:x+bw/2,y:m.t+ih+38,'text-anchor':'middle',fill:muted,'font-size':10.5});st.textContent=d.s;svg.appendChild(st);\n  });\n  const yl=el('text',{x:16,y:m.t+ih/2,'text-anchor':'middle',fill:ink2,'font-size':11.5,'font-weight':700,transform:`rotate(-90 16 ${m.t+ih/2})`});yl.textContent='Return per $1 spent';svg.appendChild(yl);\n  const t=el('text',{x:m.l+iw-6,y:Y(30)+2,'text-anchor':'end',fill:cssv('--ben'),'font-size':12.5,'font-weight':800});\n  t.textContent='more than 30-to-1';svg.appendChild(t);\n}\ndraw();\nlet rt;addEventListener('resize',()=>{clearTimeout(rt);rt=setTimeout(draw,150);});\ndocument.getElementById('themeBtn').onclick=function(){\n  const h=document.documentElement,dark=h.getAttribute('data-theme')==='dark';\n  h.setAttribute('data-theme',dark?'light':'dark');this.textContent=dark?'◐ Dark':'◑ Light';draw();};\n</script>\n</body>\n</html>\n", "CommonGround_TaxFairness_v1.html": "<!DOCTYPE html>\n<html lang=\"en\" data-theme=\"light\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>The system taxes work harder than wealth</title>\n<style>\n  :root{\n    --bg:#fcfcfb; --panel:#ffffff; --ink:#26251f; --ink2:#575349; --muted:#8a8578;\n    --line:#e7e3d8; --grid:#efece3;\n    --work:#5E86A0; --wealth:#B98A1F;\n    --shadow:0 1px 2px rgba(40,38,30,.06),0 4px 18px rgba(40,38,30,.06);\n  }\n  html[data-theme=\"dark\"]{\n    --bg:#1a1a19; --panel:#232320; --ink:#eceae2; --ink2:#c3bfb2; --muted:#928d7f;\n    --line:#38372f; --grid:#2c2b25;\n    --work:#7CA3BD; --wealth:#E0C766;\n    --shadow:0 1px 2px rgba(0,0,0,.3),0 4px 20px rgba(0,0,0,.28);\n  }\n  *{box-sizing:border-box}\n  body{margin:0;background:var(--bg);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;line-height:1.5;-webkit-font-smoothing:antialiased}\n  .wrap{max-width:860px;margin:0 auto;padding:34px 24px 70px}\n  h1{font-family:Georgia,serif;font-size:26px;margin:0 0 5px;letter-spacing:-.01em}\n  .kicker{text-transform:uppercase;letter-spacing:.09em;font-size:11px;font-weight:700;color:var(--muted);margin:0 0 4px}\n  .sub{color:var(--ink2);font-size:15px;margin:0;max-width:760px}\n  .src{color:var(--muted);font-size:12px;margin-top:6px}\n  .topbar{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap}\n  .toggle{font-size:12.5px;border:1px solid var(--line);background:var(--panel);color:var(--ink2);border-radius:20px;padding:6px 13px;cursor:pointer}\n  .legend{display:flex;gap:18px;margin:18px 0 4px;font-size:12.5px;color:var(--ink2)}\n  .legend span{display:inline-flex;align-items:center;gap:6px}\n  .sw{width:12px;height:12px;border-radius:3px;display:inline-block}\n  .panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:20px;box-shadow:var(--shadow);margin-top:8px}\n  .row{display:grid;grid-template-columns:230px 1fr;gap:14px;align-items:center;margin:14px 0}\n  @media(max-width:620px){.row{grid-template-columns:1fr}}\n  .rlab{font-size:13.5px;color:var(--ink2);font-weight:600;line-height:1.3}\n  .rlab b{color:var(--ink)}\n  .track{position:relative;background:var(--grid);border-radius:8px;height:40px;overflow:hidden}\n  .fill{height:100%;border-radius:8px;display:flex;align-items:center;justify-content:flex-end;padding-right:12px;color:#fff;font-weight:800;font-size:15px}\n  .fill.work{background:var(--work)} .fill.wealth{background:var(--wealth)}\n  .callout{background:var(--panel);border:1px solid var(--line);border-left:4px solid var(--wealth);border-radius:10px;padding:14px 16px;margin-top:14px;box-shadow:var(--shadow);font-size:13.5px;color:var(--ink2);line-height:1.55}\n  .callout b{color:var(--ink)}\n  .callout .hd{font-weight:800;font-size:14px;margin-bottom:4px;color:var(--ink)}\n  .read{font-size:14.5px;color:var(--ink2);margin-top:16px;line-height:1.6;border-left:3px solid var(--work);padding-left:16px}\n  .read b{color:var(--ink)}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <div class=\"topbar\">\n    <div>\n      <p class=\"kicker\">Common Ground · An Honest System · the problem, measured</p>\n      <h1>The system taxes work harder than wealth</h1>\n      <p class=\"sub\">The income tax is built to rise with income — and for people who live on a paycheck, it does. But at the very top, where income comes mostly from <b>wealth</b>, the effective rate bends back down. Here's the total tax rate — federal, state, and local combined — by group.</p>\n      <p class=\"src\">Source: Saez, Yagan, Zucman &amp; Balkir, NBER 2025 (IRS administrative data, 2018–2020). Total effective rate on a comprehensive measure of income.</p>\n    </div>\n    <button class=\"toggle\" id=\"themeBtn\">◐ Dark</button>\n  </div>\n\n  <div class=\"legend\">\n    <span><i class=\"sw\" style=\"background:var(--work)\"></i> income from <b>work</b></span>\n    <span><i class=\"sw\" style=\"background:var(--wealth)\"></i> income from <b>wealth</b></span>\n  </div>\n\n  <div class=\"panel\">\n    <div class=\"row\"><div class=\"rlab\"><b>Top earners who live on a salary</b></div><div class=\"track\"><div class=\"fill work\" style=\"width:100%\">45%</div></div></div>\n    <div class=\"row\"><div class=\"rlab\"><b>The average American</b></div><div class=\"track\"><div class=\"fill work\" style=\"width:67%\">30%</div></div></div>\n    <div class=\"row\"><div class=\"rlab\"><b>The 400 wealthiest Americans</b></div><div class=\"track\"><div class=\"fill wealth\" style=\"width:53%\">24%</div></div></div>\n    <div class=\"row\"><div class=\"rlab\"><b>The 100 wealthiest Americans</b></div><div class=\"track\"><div class=\"fill wealth\" style=\"width:49%\">22%</div></div></div>\n  </div>\n\n  <div class=\"callout\">\n    <div class=\"hd\">Why wealth is taxed lighter than work</div>\n    Three rules do most of it: income from <b>capital gains and dividends</b> is taxed at a lower rate than wages; a lifetime of gains on stock can <b>escape tax entirely</b> — never sold, just borrowed against to live on, and at death the \"stepped-up basis\" erases the gain, so the heirs owe nothing on it either; and the <b>payroll tax caps out</b>, so a nurse pays it on every dollar while investment income never does. <span style=\"color:var(--muted)\">(The most extreme figures — a \"3.4%\" rate — count gains that were never cashed out; the honest, narrower claim is the one shown: on a comprehensive measure, the very top pays a lower total rate than a top salaried worker.)</span>\n  </div>\n\n  <p class=\"read\"><b>Reading it.</b> A tax system is <i>supposed</i> to ask more, as a share, from those with more. It does — right up until the very top, where it quietly reverses. That's not class war to notice; it's the promise the system makes about itself, and where it isn't kept. The honest fixes are specific ones — closing the carried-interest loophole, ending \"buy, borrow, die,\" lifting the payroll cap — not a slogan about the rich paying their \"fair share.\"</p>\n</div>\n\n<script>\ndocument.getElementById('themeBtn').onclick=function(){\n  const h=document.documentElement,dark=h.getAttribute('data-theme')==='dark';\n  h.setAttribute('data-theme',dark?'light':'dark');this.textContent=dark?'◐ Dark':'◑ Light';};\n</script>\n</body>\n</html>\n"};
